import React, {useState} from 'react';
import ProfessorDetails from "../components/Professor/ProfessorDetails";
import {useParams} from "react-router";
import useProfessor from "../hooks/useProfessor";
import Popup from "../components/Popup/Popup";

function Professor(props) {
    let { endpoint } = useParams();
    console.log("questo è l'end point: ", endpoint);
    let [professor, isLoading, setProfessor] = useProfessor(endpoint);
    const [showPpopup, setShowPopup] = useState(false)
    const {professorList, onChangeProfessor, isHome} = props;

    const showPopup = () => setShowPopup(!showPpopup);

    useEffect(() => {
        const timer = setTimeout(() => {
            setShowPopup(true);
        }, 3000);
        return () => clearTimeout(timer);
    }, [showPpopup]);

    const getContent = () => {
        if(!isLoading){
            return (
                <React.Fragment>
                    {showPpopup && <Popup>
                        <div className={'form-content'}>
                            <TitlePopup titleText={'Siamo spiacenti!'} onClose={showPpopup}/>
                            <p>Potreste riscontrare errori nella visualizzazione della pagina a causa della manutenzione del server.</p>
                            <p>Ci scusiamo per il disagio.</p>
                        </div>
                    </Popup>}
                    <ProfessorDetails professorList={professorList} onChangeProfessor={onChangeProfessor} isHome={isHome} professor={professor}/>
                </React.Fragment>
            );
        }
    }

    return (
        <div>
            {getContent()}
        </div>
    )

}
export default Professor;
